-- Unregistered quote-commercial source retrieval over47 plus exact acceptance.
-- Existing export credential only; no fullCrest/recovery/activation claim.
DO $review$ BEGIN
 IF (SELECT count(*) FROM pg_roles WHERE rolname IN('crest_quote_owner','crest_export') AND NOT(rolcanlogin OR rolinherit OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls) AND rolconfig IS NULL)<>2 OR EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.roleid OR r.oid=m.member WHERE r.rolname='crest_quote_owner') OR EXISTS(SELECT 1 FROM pg_namespace WHERE nspname IN('crest','crest_private','crest_commands') AND has_schema_privilege('crest_quote_owner',oid,'CREATE')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='crest.quote_family_commercial_state'::regclass AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.quote_family_commercial_state_projection(crest.quote_family_commercial_state)') AND proowner='crest_schema_owner'::regrole AND NOT prosecdef AND provolatile='i' AND NOT proleakproof AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='19083618b92a168f2eb8723daaf7be7d69ba846fc43492b6a519f8868e304254') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='crest.quote_sends'::regclass AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.quote_sends_projection(crest.quote_sends)') AND proowner='crest_schema_owner'::regrole AND NOT prosecdef AND provolatile='i' AND NOT proleakproof AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='52afb5d01516cd726ff2b12f63bac8c98bb18d09864767f405098f99233a1f55') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='crest.quote_acceptances'::regclass AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.quote_acceptances_projection(crest.quote_acceptances)') AND proowner='crest_schema_owner'::regrole AND NOT prosecdef AND provolatile='i' AND NOT proleakproof AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='0a4422a3f8846b366fc836d32d04eeb82104b1e9bae62857e358fda5007dc63d') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='crest.agreements'::regclass AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.agreements_projection(crest.agreements)') AND proowner='crest_schema_owner'::regrole AND NOT prosecdef AND provolatile='i' AND NOT proleakproof AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='c6ea03a4ddc9680fe637cfe4e5edd3210a652dabb3d743fd61bdb10253d50315') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='crest.scope_entitlements'::regclass AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.scope_entitlements_projection(crest.scope_entitlements)') AND proowner='crest_schema_owner'::regrole AND NOT prosecdef AND provolatile='i' AND NOT proleakproof AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='19083618b92a168f2eb8723daaf7be7d69ba846fc43492b6a519f8868e304254') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='crest.entitlement_versions'::regclass AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.entitlement_versions_projection(crest.entitlement_versions)') AND proowner='crest_schema_owner'::regrole AND NOT prosecdef AND provolatile='i' AND NOT proleakproof AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='6b7e9be93804e3074c2378635ab84fd3d19f16f5993df613b7cd9a7838f1401d') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='crest.scope_allocations'::regclass AND relowner='crest_schema_owner'::regrole AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('crest_private.scope_allocations_projection(crest.scope_allocations)') AND proowner='crest_schema_owner'::regrole AND NOT prosecdef AND provolatile='i' AND NOT proleakproof AND lower(array_to_string(proconfig,','))='search_path=pg_catalog, pg_temp' AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='a1cc57329364be59aea5b6338604f7e260d7679cb2af0fe021d15464becda2fe') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_REVIEW_REQUIRED';END IF;
END $review$;
SET LOCAL ROLE crest_schema_owner;
CREATE FUNCTION crest_commands.quote_commercial_snapshot_context(requested_business uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET row_security=on AS $context$
DECLARE review jsonb;counts jsonb;total bigint;BEGIN
 IF current_setting('transaction_isolation')<>'repeatable read' OR current_setting('transaction_read_only')<>'on' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='CREST_QUOTE_COMMERCIAL_SNAPSHOT_REQUIRED';END IF;
 IF requested_business IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='CREST_QUOTE_COMMERCIAL_SCOPE_REQUIRED';END IF;
 review:=crest_commands.quote_review_snapshot_context(requested_business);
 SELECT jsonb_build_object('commercialState',(SELECT count(*)::text FROM crest.quote_family_commercial_state WHERE business_id=requested_business),'sends',(SELECT count(*)::text FROM crest.quote_sends WHERE business_id=requested_business),'acceptances',(SELECT count(*)::text FROM crest.quote_acceptances WHERE business_id=requested_business),'agreements',(SELECT count(*)::text FROM crest.agreements WHERE business_id=requested_business),'entitlements',(SELECT count(*)::text FROM crest.scope_entitlements WHERE business_id=requested_business),'entitlementVersions',(SELECT count(*)::text FROM crest.entitlement_versions WHERE business_id=requested_business),'allocations',(SELECT count(*)::text FROM crest.scope_allocations WHERE business_id=requested_business)) INTO counts;
 SELECT sum(value::bigint) INTO total FROM jsonb_each_text(counts);IF total>10000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_LIMIT';END IF;
 RETURN jsonb_build_object('schemaVersion',1,'scope','quote_commercial','businessId',requested_business,'snapshotToken',encode(sha256(convert_to(jsonb_build_object('domain','crest.quote-commercial.snapshot/1','businessId',requested_business,'snapshot',pg_current_snapshot()::text)::text,'UTF8')),'hex'),'quoteReviewSnapshotToken',review->>'snapshotToken','expectedCounts',counts);
END $context$;
CREATE FUNCTION crest_commands.quote_commercial_snapshot_commercial_state(requested_business uuid,expected_snapshot text,after_id uuid,page_limit integer) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET row_security=on AS $page$
DECLARE context jsonb;result jsonb;BEGIN context:=crest_commands.quote_commercial_snapshot_context(requested_business);IF expected_snapshot IS DISTINCT FROM context->>'snapshotToken' OR page_limit IS NULL OR page_limit NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='CREST_QUOTE_COMMERCIAL_SNAPSHOT_REQUIRED';END IF;
 WITH page AS MATERIALIZED(SELECT * FROM crest.quote_family_commercial_state WHERE business_id=requested_business AND (after_id IS NULL OR id>after_id) ORDER BY id LIMIT page_limit)
 SELECT jsonb_build_object('schemaVersion',1,'businessId',requested_business,'snapshotToken',expected_snapshot,'commercialState',coalesce(jsonb_agg(crest_private.quote_family_commercial_state_projection(p::crest.quote_family_commercial_state) ORDER BY p.id),'[]'::jsonb),'hasMore',EXISTS(SELECT 1 FROM crest.quote_family_commercial_state later WHERE later.business_id=requested_business AND later.id>(SELECT last.id FROM page last ORDER BY last.id DESC LIMIT 1))) INTO result FROM page p;IF octet_length(result::text)>4194304 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='CREST_QUOTE_COMMERCIAL_SOURCE_LIMIT';END IF;RETURN result;END $page$;
CREATE FUNCTION crest_commands.quote_commercial_snapshot_sends(requested_business uuid,expected_snapshot text,after_id uuid,page_limit integer) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET row_security=on AS $page$
